SELECT CASE WHEN ss.revenue >= 3500 THEN 'high' WHEN ss.revenue >= 1100 THEN 'mid' ELSE 'low' END AS revenue_bucket, MIN(i.quantity) AS min_quantity FROM inventory i LEFT OUTER JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE ss.sale_date BETWEEN '2023-12-01' AND '2025-05-01' GROUP BY CASE WHEN ss.revenue >= 3500 THEN 'high' WHEN ss.revenue >= 1100 THEN 'mid' ELSE 'low' END ORDER BY min_quantity DESC;
